1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #e9ecef;
16	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    background: #1f2328;
22	    border-radius: 20px;
23	    padding: 20px;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .display {
27	    color: #fff;
28	    font-size: 48px;
29	    text-align: right;
30	    padding: 16px 8px 20px;
31	    min-height: 88px;
32	    overflow: hidden;
33	    white-space: nowrap;
34	    text-overflow: ellipsis;
35	  }
36	  .keys {
37	    display: grid;
38	    grid-template-columns: repeat(4, 1fr);
39	    gap: 12px;
40	  }
41	  button {
42	    font: inherit;
43	    font-size: 24px;
44	    height: 64px;
45	    border: none;
46	    border-radius: 14px;
47	    background: #3a3f45;
48	    color: #fff;
49	    cursor: pointer;
50	  }
51	  button:active { filter: brightness(1.25); }
52	  button.op { background: #f59f00; }
53	  button.op.active { background: #fff; color: #f59f00; }
54	  button.clear { background: #868e96; }
55	  button.wide { grid-column: span 2; }
56	</style>
57	</head>
58	<body>
59	<div class="calc">
60	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
61	  <div class="keys">
62	    <button class="clear wide" data-testid="key-lparen">(</button>
63	    <button class="clear wide" data-testid="key-rparen">)</button>
64	
65	    <button class="clear" data-testid="key-clear">AC</button>
66	    <button class="clear" data-testid="key-sign">±</button>
67	    <button class="clear" data-testid="key-percent">%</button>
68	    <button class="op" data-testid="key-div" data-op="/">÷</button>
69	
70	    <button data-testid="key-7">7</button>
71	    <button data-testid="key-8">8</button>
72	    <button data-testid="key-9">9</button>
73	    <button class="op" data-testid="key-mul" data-op="*">×</button>
74	
75	    <button data-testid="key-4">4</button>
76	    <button data-testid="key-5">5</button>
77	    <button data-testid="key-6">6</button>
78	    <button class="op" data-testid="key-sub" data-op="-">−</button>
79	
80	    <button data-testid="key-1">1</button>
81	    <button data-testid="key-2">2</button>
82	    <button data-testid="key-3">3</button>
83	    <button class="op" data-testid="key-add" data-op="+">+</button>
84	
85	    <button class="wide" data-testid="key-0">0</button>
86	    <button data-testid="key-dot">.</button>
87	    <button class="op" data-testid="key-equals">=</button>
88	  </div>
89	</div>
90	<script>
91	  var display = document.querySelector('[data-testid="calc-display"]');
92	
93	  var state = {
94	    entry: '0',       // text of the number being shown/typed
95	    stored: null,     // left operand
96	    op: null,         // pending operator
97	    fresh: true,      // next digit starts a new entry
98	    typed: false,     // entry was typed by the user (shown as typed, not formatted)
99	    error: false,
100	    groups: []        // [REQ-005] saved {stored, op} of each open "(", innermost last
101	  };
102	
103	  // [REQ-003] Presentation only: at most 10 significant digits, no trailing
104	  // zeros, exponential when |v| >= 1e10 or < 1e-9. Never applied to stored values.
105	  function formatNumber(v) {
106	    var r = Number(v.toPrecision(10));
107	    if (r === 0) return '0';
108	    var abs = Math.abs(r);
109	    if (abs >= 1e10 || abs < 1e-9) {
110	      return r.toExponential(9).replace(/\.?0+e/, 'e');
111	    }
112	    var e = Math.floor(Math.log10(abs));
113	    var s = r.toFixed(Math.max(0, 10 - e));
114	    if (s.indexOf('.') !== -1) s = s.replace(/0+$/, '').replace(/\.$/, '');
115	    return s;
116	  }
117	
118	  // [REQ-001]
119	  function compute(a, op, b) {
120	    switch (op) {
121	      case '+': return a + b;
122	      case '-': return a - b;
123	      case '*': return a * b;
124	      case '/': return a / b;
125	    }
126	    return b;
127	  }
128	
129	  // [REQ-001]
130	  // [REQ-003] Rounding happens here only; data-value keeps the exact value.
131	  function render() {
132	    var value = Number(state.entry);
133	    display.textContent = state.error ? 'Error' : (state.typed ? state.entry : formatNumber(value));
134	    display.setAttribute('data-value', state.error ? 'NaN' : String(value));
135	    display.setAttribute('data-error', state.error ? 'true' : 'false');
136	    document.querySelectorAll('button[data-op]').forEach(function (b) {
137	      b.classList.toggle('active', state.fresh && state.op === b.getAttribute('data-op'));
138	    });
139	  }
140	
141	  // [REQ-001]
142	  // [REQ-003] Division by zero (non-finite result) enters the error state.
143	  // String(value) is exact: Number(String(v)) === v.
144	  function setResult(value) {
145	    if (!isFinite(value)) {
146	      state.error = true;
147	      state.entry = '0';
148	      state.stored = null;
149	      state.op = null;
150	      state.groups = [];
151	    } else {
152	      state.entry = String(value);
153	    }
154	    state.typed = false;
155	    state.fresh = true;
156	  }
157	
158	  // [REQ-001]
159	  // [REQ-003] Ignored in the error state; only clear leaves it.
160	  // [REQ-004] A value set by ± or % is finished: the next digit starts a new entry.
161	  function inputDigit(d) {
162	    if (state.error) return;
163	    if (state.fresh || !state.typed) {
164	      state.entry = d;
165	      state.fresh = false;
166	    } else if (state.entry === '0' || state.entry === '-0') {
167	      state.entry = state.entry.slice(0, -1) + d;
168	    } else {
169	      state.entry += d;
170	    }
171	    state.typed = true;
172	  }
173	
174	  // [REQ-001]
175	  // [REQ-003] Ignored in the error state.
176	  function inputDot() {
177	    if (state.error) return;
178	    if (state.fresh || !state.typed) {
179	      state.entry = '0.';
180	      state.fresh = false;
181	    } else if (state.entry.indexOf('.') === -1) {
182	      state.entry += '.';
183	    }
184	    state.typed = true;
185	  }
186	
187	  // [REQ-004] ± flips the current entry. While typing it flips the text, so
188	  // typing continues. Otherwise the flipped value becomes the current operand.
189	  function toggleSign() {
190	    if (state.error) return;
191	    if (state.typed && !state.fresh) {
192	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
193	    } else {
194	      setOperand(-Number(state.entry));
195	    }
196	  }
197	
198	  // [REQ-004] % divides the current entry by 100; the result is the current operand.
199	  function percent() {
200	    if (state.error) return;
201	    setOperand(Number(state.entry) / 100);
202	  }
203	
204	  // [REQ-004] A finished value that counts as the right operand if an operator
205	  // is waiting (so 2 + 50 % = is 2.5), and is replaced by the next digit.
206	  function setOperand(value) {
207	    state.entry = String(value);
208	    state.typed = false;
209	    state.fresh = false;
210	  }
211	
212	  // [REQ-001]
213	  // [REQ-002] Immediate execution: an operator key first finishes the waiting
214	  // operation, strictly left to right, no precedence. 2 + 3 × 4 = is 20.
215	  function inputOperator(op) {
216	    if (state.error) return;
217	    if (state.op !== null && !state.fresh) {
218	      setResult(compute(state.stored, state.op, Number(state.entry)));
219	      if (state.error) return;
220	    }
221	    state.stored = Number(state.entry);
222	    state.op = op;
223	    state.fresh = true;
224	  }
225	
226	  // [REQ-005] "(" saves the waiting operation and starts an empty group.
227	  // Whatever the group evaluates to replaces the current entry.
228	  function openGroup() {
229	    if (state.error) return;
230	    state.groups.push({ stored: state.stored, op: state.op });
231	    state.stored = null;
232	    state.op = null;
233	    state.entry = '0';
234	    state.fresh = true;
235	    state.typed = false;
236	  }
237	
238	  // [REQ-005] ")" finishes the innermost group, restores the operation that
239	  // was waiting outside it, and uses the group's value as its right operand.
240	  // Ignored when no group is open.
241	  function closeGroup() {
242	    if (state.error || state.groups.length === 0) return;
243	    var value = state.op === null ? Number(state.entry)
244	      : compute(state.stored, state.op, Number(state.entry));
245	    if (!isFinite(value)) { setResult(value); return; }
246	    var outer = state.groups.pop();
247	    state.stored = outer.stored;
248	    state.op = outer.op;
249	    setOperand(value);
250	  }
251	
252	  // [REQ-001]
253	  // [REQ-005] Open groups are closed first, so 2 × ( 3 + 4 = is 14.
254	  function equals() {
255	    if (state.error) return;
256	    while (state.groups.length > 0 && !state.error) closeGroup();
257	    if (state.error || state.op === null) return;
258	    var result = compute(state.stored, state.op, Number(state.entry));
259	    state.stored = null;
260	    state.op = null;
261	    setResult(result);
262	  }
263	
264	  // [REQ-001]
265	  function clearAll() {
266	    state.entry = '0';
267	    state.stored = null;
268	    state.op = null;
269	    state.fresh = true;
270	    state.typed = false;
271	    state.error = false;
272	    state.groups = [];
273	  }
274	
275	  document.querySelector('.keys').addEventListener('click', function (e) {
276	    var btn = e.target.closest('button');
277	    if (!btn) return;
278	    var id = btn.getAttribute('data-testid');
279	    if (/^key-\d$/.test(id)) inputDigit(id.slice(4));
280	    else if (id === 'key-dot') inputDot();
281	    else if (id === 'key-sign') toggleSign();
282	    else if (id === 'key-percent') percent();
283	    else if (id === 'key-lparen') openGroup();
284	    else if (id === 'key-rparen') closeGroup();
285	    else if (id === 'key-equals') equals();
286	    else if (id === 'key-clear') clearAll();
287	    else if (btn.hasAttribute('data-op')) inputOperator(btn.getAttribute('data-op'));
288	    render();
289	  });
290	
291	  render();
292	</script>
293	</body>
294	</html>
